FactoryBot.define do
  factory :user do
    sequence(:email) { |number| "user#{number}@example.com" }
    status { :active }

    trait :suspended do
      status { :suspended }
      suspended_at { Time.now.utc }
    end
  end
end

user = FactoryBot.build(:user, :suspended)
puts [user.email, user.status, !user.suspended_at.nil?].join(" | ")
